import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
    const [contacts, setContacts] = useState([]);
    const [formData, setFormData] = useState({ name: '', phone: '', email: '', address: '' });
    const [editingId, setEditingId] = useState(null);

    // Fetch contacts
    useEffect(() => {
        axios.get('http://localhost:5000/contacts')
            .then((response) => setContacts(response.data))
            .catch((error) => console.error(error));
    }, []);

    // Handle form submission
    const handleSubmit = (e) => {
        e.preventDefault();
        if (editingId) {
            axios.put(`http://localhost:5000/contacts/${editingId}`, formData)
                .then((response) => {
                    setContacts(contacts.map(contact => (contact.id === editingId ? response.data : contact)));
                    setEditingId(null);
                    setFormData({ name: '', phone: '', email: '', address: '' });
                });
        } else {
            axios.post('http://localhost:5000/contacts', formData)
                .then((response) => {
                    setContacts([...contacts, response.data]);
                    setFormData({ name: '', phone: '', email: '', address: '' });
                });
        }
    };

    // Handle delete
    const handleDelete = (id) => {
        axios.delete(`http://localhost:5000/contacts/${id}`)
            .then(() => setContacts(contacts.filter(contact => contact.id !== id)));
    };

    return (
        <div>
            <h1>Contact Management</h1>
            <form onSubmit={handleSubmit}>
                <input
                    type="text"
                    placeholder="Name"
                    value={formData.name}
                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                />
                <input
                    type="text"
                    placeholder="Phone"
                    value={formData.phone}
                    onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                />
                <input
                    type="text"
                    placeholder="Email"
                    value={formData.email}
                    onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                />
                <input
                    type="text"
                    placeholder="Address"
                    value={formData.address}
                    onChange={(e) => setFormData({ ...formData, address: e.target.value })}
                />
                <button type="submit">{editingId ? 'Update' : 'Add'} Contact</button>
            </form>
            <ul>
                {contacts.map((contact) => (
                    <li key={contact.id}>
                        {contact.name} - {contact.phone} - {contact.email} - {contact.address}
                        <button onClick={() => {
                            setEditingId(contact.id);
                            setFormData(contact);
                        }}>Edit</button>
                        <button onClick={() => handleDelete(contact.id)}>Delete</button>
                    </li>
                ))}
            </ul>
        </div>
    );
}

export default App;
